"""Migration of the Meridian CRM 4.2 case-escalation nightly job."""

from datetime import datetime


def _datediff(today: str, open_date: object) -> int:
    """Return legacy DATEDIFF(today, open_date) whole calendar days."""
    if today in ("", "00000000", None) or open_date in ("", "00000000", None):
        return 0

    start = datetime.strptime(str(open_date), "%Y%m%d").date()
    end = datetime.strptime(str(today), "%Y%m%d").date()
    return (end - start).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation workflow events in legacy CASE_ID order."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: str(row.get("CASE_ID", ""))):
        if case.get("DEL_FLG") == "Y":
            continue

        status = case.get("STAT_CD")
        days_open = _datediff(today, case.get("OPEN_DT", ""))

        should_escalate = (
            status == "N" and days_open >= 2
        ) or (
            status == "A"
            and case.get("ESC_FLG", "") != "Y"
            and days_open >= 7
        )

        if should_escalate:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

    return events
